import { useState, useEffect } from 'react';
import { Save } from 'lucide-react';
import { useSheets } from '../hooks/useSheets';
import { fmt, getCurrentYM } from '../utils/format';
import { STORES, BRANDS } from '../utils/config';
import { buildCostMap, calcShoplineTotals, calcMomoTotals, calcShopeeTotals, calcErpTotals, calcOrdersTotals, splitByStore, mergeUnmatched } from '../utils/salesCalc';

const EXPENSE_ITEMS = [
  '人員薪資','勞健保','房租','電費','網路費',
  '行銷費用－平台廣告費','行銷費用－商品搭贈',
  '運費','包材/雜支','平均攤提費用','其他費用',
];

// 每個月都是從 0 開始輸入，不能用上個月留下來的物件參照（避免共用同一份物件被改到）
const ZERO_AD_COST  = () => Object.fromEntries(STORES.map(s => [s.id, 0]));
const ZERO_EXPENSES = () => Object.fromEntries(EXPENSE_ITEMS.map(k => [k, 0]));
// 自訂費用項目（不在上面固定清單裡的，使用者自己新增名稱）：[{ id, name, amount, note }, ...]
const ZERO_CUSTOM   = () => [];
let customIdSeq = 0;
const newCustomRow = () => ({ id: `c${Date.now()}_${customIdSeq++}`, name:'', amount:0, note:'' });

// 「全部期間」檢視時，自訂費用改成把每個月存過的項目依「名稱」加總起來
// （同一個名稱在不同月份都有填的話，全部期間會顯示加總金額；備註取最後一次有填的那筆）。
function sumCustomExpensesByMonth(byMonth) {
  const merged = {}; // name -> { name, amount, note }
  Object.values(byMonth || {}).forEach(entry => {
    (entry?.customExpenses || []).forEach(row => {
      const name = (row?.name || '').trim();
      if (!name) return;
      const amt = Number(row.amount) || 0;
      if (!merged[name]) merged[name] = { id:name, name, amount:0, note: row.note || '' };
      merged[name].amount += amt;
      if (row.note) merged[name].note = row.note;
    });
  });
  return Object.values(merged);
}

// 「全部期間」檢視時，廣告費/其他費用改成顯示「每個月分別存過的金額」加總起來，
// 不是隨便挑一筆數字套用——這樣才符合「每個月各自輸入」的真實情況。
function sumPnlByMonth(byMonth, field) {
  const sums = {};
  Object.values(byMonth || {}).forEach(entry => {
    const obj = (entry && entry[field]) || {};
    Object.keys(obj).forEach(k => { sums[k] = (sums[k] || 0) + (Number(obj[k]) || 0); });
  });
  return sums;
}

export default function PnlPage() {
  const { savePnlData, loadPnlData, readAllSales, readProducts } = useSheets();
  const [tab, setTab] = useState('store');
  // adCost/expenses 是「目前選定月份」正在編輯的費用（每次切月份都會重新從 pnlByMonth 同步過來）。
  const [adCost, setAdCost] = useState(ZERO_AD_COST);
  const [expenses, setExpenses] = useState(ZERO_EXPENSES);
  // 自訂費用項目（使用者自己建立名稱的費用，不在上面11個固定項目裡）
  const [customExpenses, setCustomExpenses] = useState(ZERO_CUSTOM);
  // pnlByMonth：{ "2026-09": {adCost, expenses}, "2026-10": {...}, ... }——每個月各自存過的費用，
  // 這是解決「廣告費套用到每個月」這個 bug 的關鍵：不再是單一一組數字，而是依年月分開存放。
  const [pnlByMonth, setPnlByMonth] = useState({});
  const [saved, setSaved] = useState(false);
  // 原始銷售資料先整包存起來，實際的營收/成本改成依下面選的月份/全部檢視即時算，
  // 不用每次切換月份都重新打 Sheets API。
  const [rawSales, setRawSales] = useState({ shopline:[], momo:[], shopee:[], erp:[], orders:[] });
  const [costMap, setCostMap] = useState({});
  // 月份切換（右上角）：跟銷貨總表一樣，viewMode='all' 顯示全部歷史、'month' 只看 ym 那個月。
  // 經銷(ERP)原始資料完全沒有日期欄位，選特定月份時經銷一律算 0，只會出現在「全部」檢視。
  const [viewMode, setViewMode] = useState('month');
  const [ym, setYm] = useState(() => getCurrentYM());

  const monthStr = `${ym.year}-${String(ym.month).padStart(2,'0')}`;

  // 載入已儲存的費用資料（依年月分開的整包資料），並同步目前這個月份的編輯框。
  useEffect(() => {
    loadPnlData().then(byMonth => {
      setPnlByMonth(byMonth);
      const rec = byMonth[monthStr];
      setAdCost(rec?.adCost ? { ...ZERO_AD_COST(), ...rec.adCost } : ZERO_AD_COST());
      setExpenses(rec?.expenses ? { ...ZERO_EXPENSES(), ...rec.expenses } : ZERO_EXPENSES());
      setCustomExpenses(rec?.customExpenses?.length ? rec.customExpenses : ZERO_CUSTOM());
    }).catch(() => {});
    // 載入真實銷售資料
    // 注意：欄位索引請對照 utils/salesCalc.js 的說明，跟 excelParser.js 實際寫入 Sheets 的欄位順序一致。
    // 這裡曾經用錯欄位（例如經銷用了「稅額」欄位當總金額，官網用了「單價」欄位當總金額），
    // 算出來的銷貨收入長期偏低，已經修正；成本也改成用商品總表的真實含稅成本計算，不再用「營收 × 40%」的粗估。
    Promise.all([readAllSales(), readProducts()]).then(([sales, products]) => {
      // readProducts() 已經把套組/多入組的成本從套組成分表換算好了，這裡不用再另外處理
      setCostMap(buildCostMap(products));
      setRawSales(sales);
    }).catch(() => {});
  }, []);

  // 切換月份時，把編輯框換成「那個月」已經存過的資料；沒存過就整組歸零，
  // 逼使用者針對新選的月份重新輸入，不會沿用前一個月份還留在畫面上的數字。
  useEffect(() => {
    if (viewMode !== 'month') return;
    const rec = pnlByMonth[monthStr];
    setAdCost(rec?.adCost ? { ...ZERO_AD_COST(), ...rec.adCost } : ZERO_AD_COST());
    setExpenses(rec?.expenses ? { ...ZERO_EXPENSES(), ...rec.expenses } : ZERO_EXPENSES());
    setCustomExpenses(rec?.customExpenses?.length ? rec.customExpenses : ZERO_CUSTOM());
    setSaved(false);
  }, [monthStr]);

  // 「全部期間」檢視時用加總顯示（不可編輯）；「月份」檢視時用目前編輯框裡的值。
  const effectiveAdCost   = viewMode === 'all' ? sumPnlByMonth(pnlByMonth, 'adCost')   : adCost;
  const effectiveExpenses = viewMode === 'all' ? sumPnlByMonth(pnlByMonth, 'expenses') : expenses;
  const effectiveCustom   = viewMode === 'all' ? sumCustomExpensesByMonth(pnlByMonth)  : customExpenses;

  const addCustomRow = () => setCustomExpenses(prev => [...prev, newCustomRow()]);
  const updateCustomRow = (id, field, val) =>
    setCustomExpenses(prev => prev.map(r => r.id === id ? { ...r, [field]: val } : r));
  const removeCustomRow = (id) => setCustomExpenses(prev => prev.filter(r => r.id !== id));

  const handleSave = async () => {
    if (viewMode === 'all') return; // 全部期間是加總顯示，沒有單一月份可以存
    // 存檔前把名稱是空白的自訂費用行濾掉，不要存一堆空列
    const cleanCustom = customExpenses.filter(r => (r.name || '').trim());
    await savePnlData(ym.year, ym.month, adCost, expenses, cleanCustom).catch(() => {});
    setPnlByMonth(prev => ({ ...prev, [monthStr]: { adCost, expenses, customExpenses: cleanCustom } }));
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const shiftMonth = (delta) => {
    setViewMode('month');
    setYm(p => {
      let m = p.month + delta, y = p.year;
      if (m < 1) { m = 12; y -= 1; }
      if (m > 12) { m = 1; y += 1; }
      return { year:y, month:m };
    });
  };

  // 依目前選擇的月份/全部檢視，篩出各平台要拿去算營收成本的資料列。
  // dateIdx=null（經銷ERP）代表這個平台完全沒有日期欄位，選特定月份時一定回傳空陣列。
  // （monthStr 已經在上面定義過，這裡沿用同一個）
  const applyView = (rows, dateIdx) => {
    if (viewMode === 'all') return rows || [];
    if (dateIdx == null) return [];
    return (rows || []).filter(r => String(r[dateIdx] || '').startsWith(monthStr));
  };
  const shoplineView = applyView(rawSales.shopline, 1);
  const momoView     = applyView(rawSales.momo, 1);
  const shopeeView   = applyView(rawSales.shopee, 1);
  const ordersView   = applyView(rawSales.orders, 1);
  const erpView      = viewMode === 'all' ? (rawSales.erp || []) : [];

  // 官網/蝦皮同時裝著 TOOLA 和拓屋兩個賣場的資料，靠每一列最後一欄的賣場標記分開——
  // 之前這裡把整包 shopline/shopee 都算成 TOOLA 賣場，拓屋官網/蝦皮的營收永遠是 0，已修正。
  const shoplineByStore = splitByStore(shoplineView);
  const shopeeByStore   = splitByStore(shopeeView);

  const storeRevenue = {
    TOOLA_SHOPLINE:  calcShoplineTotals(shoplineByStore.TOOLA_SHOPLINE, costMap),
    TAKUYA_SHOPLINE: calcShoplineTotals(shoplineByStore.TAKUYA_SHOPLINE, costMap),
    MOMO:            calcMomoTotals(momoView, costMap),
    TOOLA_SHOPEE:    calcShopeeTotals(shopeeByStore.TOOLA_SHOPEE, costMap),
    TAKUYA_SHOPEE:   calcShopeeTotals(shopeeByStore.TAKUYA_SHOPEE, costMap),
    ERP:             calcErpTotals(erpView, costMap),
  };
  // 手動開單（OrderPage 開的單）的營收/成本——
  // 之前這裡完全沒有把 orders 分頁的資料算進損益表，只有銷貨總表看得到手動開單，
  // 損益表的「銷貨收入」會比銷貨總表少（漏了手動開單那一塊），兩個頁面數字對不起來。
  // 手動開單的「管道」是自由文字（官網/momo/蝦皮/經銷/現場/其他），沒辦法可靠對應到
  // 某一個特定賣場或品牌，所以先獨立列一行「手動開單」，不硬塞進某個賣場列，
  // 至少讓公司總損益表的營收/成本數字是完整、對得起來的。
  const ordersTotals = calcOrdersTotals(ordersView, costMap);
  const ordersRevenue = { revenue: ordersTotals.revenue, cost: ordersTotals.cost };

  // 「銷貨成本」是不是有真的帶入商品成本，答案是：本來就是（跟銷貨總表用同一套 costMap，
  // 都是拿商品代號去查商品總表／套組成分表的真實含稅成本 × 數量）。如果這裡看到「銷貨成本 $0」
  // 但銷貨收入不是0，代表這段期間賣出的商品代號，商品總表／套組成分表都查無資料（不是系統
  // 沒有去抓，是根本沒有成本資料可以抓）。之前這個提醒只有銷貨總表（SalesPage.js）會顯示，
  // 損益表這裡看不到原因，容易誤以為「成本沒有撈到」是系統的問題，所以在這裡也加上同樣的
  // 查無資料清單，方便直接在損益表這頁看到哪些代號需要去商品總表/套組成分表補建檔。
  const allUnmatched = mergeUnmatched(
    ...Object.values(storeRevenue).map(d => d.unmatched),
    ordersTotals.unmatched,
  );
  const unmatchedRevenue = allUnmatched.reduce((s, u) => s + (u.revenue || 0), 0);

  const storeRows = STORES.map(s => {
    const d = storeRevenue[s.id] || { revenue:0, cost:0 };
    const ad = Number(effectiveAdCost[s.id]) || 0;
    const gross = d.revenue - d.cost;
    const net = gross - ad;
    const roi = ad > 0 ? (d.revenue / ad).toFixed(1) : null;
    return { ...s, ...d, ad, gross, net, roi };
  });

  const totalRevenue  = storeRows.reduce((a,s) => a+s.revenue, 0) + ordersRevenue.revenue;
  const totalCost     = storeRows.reduce((a,s) => a+s.cost, 0) + ordersRevenue.cost;
  const totalAd       = storeRows.reduce((a,s) => a+s.ad, 0);
  const totalGross    = totalRevenue - totalCost;
  const totalCustomExpenses = effectiveCustom.reduce((a,r) => a+(Number(r.amount)||0), 0);
  const totalExpenses = Object.values(effectiveExpenses).reduce((a,b) => a+(Number(b)||0), 0) + totalCustomExpenses;
  const totalNet      = totalGross - totalAd - totalExpenses;

  const TABS = [
    { id:'store', label:'各賣場廣告費' },
    { id:'brand', label:'品牌損益' },
    { id:'total', label:'公司損益表' },
  ];
  const periodLabel = viewMode === 'all' ? '全部期間' : `${ym.year}年${ym.month}月`;

  return (
    <div>
      <div className="flex-between mb-16">
        <div style={{ display:'flex', gap:4 }}>
          {TABS.map(t => (
            <button key={t.id}
              className={`btn btn-sm ${tab===t.id ? 'btn-primary' : 'btn-ghost'}`}
              onClick={() => setTab(t.id)}>
              {t.label}
            </button>
          ))}
        </div>
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          <button className={`btn btn-sm ${viewMode==='all'?'btn-primary':'btn-ghost'}`}
            onClick={() => setViewMode('all')}>全部期間</button>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(-1)}>‹</button>
          <span style={{ fontSize:14, color:'var(--text)', minWidth:78, textAlign:'center', fontFamily:'var(--mono)' }}>
            {viewMode==='all' ? '全部' : `${ym.year}年${ym.month}月`}
          </span>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(1)}>›</button>
          <button className="btn btn-primary btn-sm" onClick={handleSave} disabled={viewMode==='all'}
            title={viewMode==='all' ? '全部期間是加總顯示，請切換到特定月份才能輸入/儲存費用' : undefined}
            style={viewMode==='all' ? { opacity:0.4, cursor:'not-allowed' } : undefined}>
            <Save size={15}/> {saved ? '✓ 已儲存' : '儲存'}
          </button>
        </div>
      </div>
      {viewMode !== 'all' && (
        <div style={{ fontSize:12, color:'var(--muted)', marginTop:-10, marginBottom:16 }}>
          ◈ 經銷(ERP)報表沒有日期欄位，選擇特定月份時不會計入，只會出現在「全部期間」檢視。
        </div>
      )}
      {viewMode === 'all' && (
        <div style={{ fontSize:12, color:'var(--muted)', marginTop:-10, marginBottom:16 }}>
          ◈ 廣告費、其他營業費用本來就要照每個月分別輸入——這裡「全部期間」顯示的是每個月已經存過的金額加總起來，
          不能在這裡編輯，請切換到「‹ 月份 ›」才能輸入/修改那個月自己的費用。
        </div>
      )}

      {allUnmatched.length > 0 && (
        <div style={{ background:'rgba(255,196,0,0.08)', border:'1px solid rgba(255,196,0,0.35)', borderRadius:8, padding:'10px 14px', marginBottom:16, fontSize:13, color:'var(--yellow, #f5c400)' }}>
          ⚠ 銷貨成本已經是抓商品總表／套組成分表的真實含稅成本計算，不是用比例估算的——但{periodLabel}賣出的代號裡，
          有 {allUnmatched.length} 個（共 {fmt.currency(unmatchedRevenue)} 營收）在商品總表、套組成分表都查無資料，
          這些代號的成本目前算成 $0（不是真的免費，是還沒建檔），所以下面的「銷貨成本」會偏低。
          麻煩到 Google Sheets 的「商品總表」（多入組/套組請到「套組成分表」）把這些代號補上：
          {' '}{allUnmatched.slice(0, 8).map(u => u.code).join('、')}{allUnmatched.length > 8 ? ` 等共 ${allUnmatched.length} 個代號` : ''}
          （完整清單可以到「銷貨總表」頁面查看紅字標示）。
        </div>
      )}

      {tab === 'store' && (
        <div className="card">
          <div className="card-title">各賣場廣告費輸入 <span>{periodLabel} · {viewMode==='all' ? '每月加總顯示，不可編輯' : '黃底可直接輸入（請輸入含稅金額）'}</span></div>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>賣場</th><th>品牌</th>
                  <th style={{ textAlign:'right' }}>銷售收入</th>
                  <th style={{ textAlign:'right' }}>銷貨成本</th>
                  <th style={{ textAlign:'right' }}>毛利</th>
                  <th style={{ textAlign:'right', background:'rgba(245,196,0,0.1)', color:'var(--yellow)' }}>廣告費用</th>
                  <th style={{ textAlign:'right' }}>賣場淨利</th>
                  <th style={{ textAlign:'right' }}>ROI</th>
                </tr>
              </thead>
              <tbody>
                {storeRows.map(s => {
                  const brand = BRANDS[s.brand] || BRANDS.TOOLA;
                  return (
                    <tr key={s.id}>
                      <td style={{ fontWeight:600 }}>{s.name}</td>
                      <td>
                        <span style={{ fontSize:11, color:brand.color, background:brand.bg, padding:'2px 7px', borderRadius:3, border:`1px solid ${brand.color}40`, letterSpacing:1 }}>
                          {s.brand === 'ALL' ? '共用' : brand.name}
                        </span>
                      </td>
                      <td className="td-right td-mono" style={{ color:'var(--cyan)' }}>{fmt.currency(s.revenue)}</td>
                      <td className="td-right td-mono" style={{ color:'var(--pink)' }}>{fmt.currency(s.cost)}</td>
                      <td className="td-right td-mono" style={{ color:'var(--green)' }}>{fmt.currency(s.gross)}</td>
                      <td style={{ padding:0 }}>
                        <div className="money-input" style={viewMode==='all' ? { opacity:0.55 } : undefined}>
                          <span className="money-input-prefix">$</span>
                          <input type="text" inputMode="numeric"
                            disabled={viewMode==='all'}
                            value={s.ad ? Number(s.ad).toLocaleString() : ''}
                            placeholder={viewMode==='all' ? '—' : '點擊輸入'}
                            onChange={e => { const v = Number(e.target.value.replace(/,/g,'')); setAdCost(p => ({ ...p, [s.id]:isNaN(v)?0:v })); setSaved(false); }}
                          />
                        </div>
                      </td>
                      <td className="td-right td-mono" style={{ color: s.net>=0?'var(--green)':'var(--pink)', fontWeight:600 }}>
                        {fmt.currency(s.net)}
                      </td>
                      <td className="td-right td-mono" style={{ color: s.roi ? (Number(s.roi)>=3?'var(--green)':'var(--yellow)') : 'var(--muted)' }}>
                        {s.roi ? `${s.roi}x` : '–'}
                      </td>
                    </tr>
                  );
                })}
                {ordersRevenue.revenue > 0 && (
                  <tr>
                    <td style={{ fontWeight:600 }}>手動開單</td>
                    <td>
                      <span style={{ fontSize:11, color:'var(--muted)', background:'rgba(224,224,255,0.06)', padding:'2px 7px', borderRadius:3, border:'1px solid rgba(224,224,255,0.15)', letterSpacing:1 }}>
                        混合
                      </span>
                    </td>
                    <td className="td-right td-mono" style={{ color:'var(--cyan)' }}>{fmt.currency(ordersRevenue.revenue)}</td>
                    <td className="td-right td-mono" style={{ color:'var(--pink)' }}>{fmt.currency(ordersRevenue.cost)}</td>
                    <td className="td-right td-mono" style={{ color:'var(--green)' }}>{fmt.currency(ordersRevenue.revenue - ordersRevenue.cost)}</td>
                    <td style={{ textAlign:'center', color:'var(--muted)', fontSize:12 }}>不適用</td>
                    <td className="td-right td-mono" style={{ color:'var(--green)', fontWeight:600 }}>{fmt.currency(ordersRevenue.revenue - ordersRevenue.cost)}</td>
                    <td className="td-right td-mono" style={{ color:'var(--muted)' }}>–</td>
                  </tr>
                )}
              </tbody>
              <tfoot>
                <tr style={{ background:'rgba(0,245,255,0.06)', borderTop:'1px solid rgba(0,245,255,0.3)' }}>
                  <td colSpan={2} style={{ fontFamily:'var(--title)', fontWeight:700, color:'var(--cyan)', letterSpacing:2, padding:'11px 14px' }}>合計</td>
                  <td className="td-right">{fmt.currency(totalRevenue)}</td>
                  <td className="td-right" style={{ color:'var(--pink)' }}>{fmt.currency(totalCost)}</td>
                  <td className="td-right" style={{ color:'var(--green)' }}>{fmt.currency(totalGross)}</td>
                  <td className="td-right" style={{ color:'var(--yellow)' }}>{fmt.currency(totalAd)}</td>
                  <td className="td-right" style={{ color: (totalGross-totalAd)>=0?'var(--green)':'var(--pink)', fontWeight:700 }}>{fmt.currency(totalGross-totalAd)}</td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>
          <div style={{ marginTop:10, fontSize:14, color:'var(--muted)', letterSpacing:1 }}>
            ◈ ROI = 銷售收入 ÷ 廣告費　◈ ROI ≥ 3x 顯示綠色　◈ 其他費用在「公司損益表」輸入
          </div>
        </div>
      )}

      {tab === 'brand' && (
        <div>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(1,1fr)', gap:12, marginBottom:16 }}>
            {['TOOLA','LEON','TAKUYA'].map(bid => {
              const brand = BRANDS[bid];
              const stores = storeRows.filter(s => s.brand === bid);
              const rev  = stores.reduce((a,s) => a+s.revenue, 0);
              const cost = stores.reduce((a,s) => a+s.cost, 0);
              const ad   = stores.reduce((a,s) => a+s.ad, 0);
              const gross = rev - cost;
              const net   = gross - ad;
              return (
                <div key={bid} style={{ background:brand.bg, border:`1px solid ${brand.color}30`, borderRadius:4, padding:18 }}>
                  <div style={{ fontFamily:'var(--title)', fontSize:16, fontWeight:700, color:brand.color, letterSpacing:2, marginBottom:14 }}>{brand.name}</div>
                  {[
                    { label:'銷售收入', value:rev,   color:brand.color },
                    { label:'銷貨成本', value:cost,  color:'var(--pink)' },
                    { label:'毛利',     value:gross, color:'var(--green)' },
                    { label:'廣告費用', value:ad,    color:'var(--yellow)' },
                    { label:'賣場淨利', value:net,   color: net>=0?'var(--green)':'var(--pink)', big:true },
                  ].map(({ label, value, color, big }) => (
                    <div key={label} style={{ display:'flex', justifyContent:'space-between', padding:'6px 0', borderBottom:'1px solid rgba(255,255,255,0.04)' }}>
                      <span style={{ fontSize:13, color:'var(--muted)' }}>{label}</span>
                      <span style={{ fontSize:big?16:14, fontWeight:big?700:400, color, fontFamily:'var(--mono)' }}>{fmt.currency(value)}</span>
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
          <div className="card" style={{ background:'rgba(0,245,255,0.02)' }}>
            <div className="card-title">momo / 經銷（跨品牌）<span>串接 Google Sheets 後自動依產品代號拆分品牌</span></div>
            <div style={{ fontSize:14, color:'var(--muted)', lineHeight:2 }}>
              ◈ momo 和經銷報表同時包含多個品牌的商品<br/>
              ◈ 串接後系統會依產品代號前綴（BDTL / BDLN）自動拆分各品牌收入<br/>
              {ordersRevenue.revenue > 0 && <>◈ 手動開單目前共 {fmt.currency(ordersRevenue.revenue)} 營收沒有算進上面三個品牌卡片，只會出現在「公司損益表」的總額裡（管道欄位是自由填寫，沒辦法自動判斷屬於哪個品牌）</>}
            </div>
          </div>
        </div>
      )}

      {tab === 'total' && (
        <div className="grid-2">
          <div className="card">
            <div className="card-title">公司損益表 <span>{periodLabel}</span></div>
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th style={{ width:'65%' }}>項目</th>
                    <th style={{ textAlign:'right' }}>金額 (NTD)</th>
                  </tr>
                </thead>
                <tbody>
                  <tr className="pnl-section-row"><td colSpan={2} style={{ paddingLeft:16 }}>一、銷貨收入</td></tr>
                  {storeRows.map(s => (
                    <tr key={s.id}>
                      <td style={{ paddingLeft:28 }}>{s.name}</td>
                      <td style={{ textAlign:'right', fontFamily:'var(--mono)', color:'var(--cyan)' }}>{fmt.currency(s.revenue)}</td>
                    </tr>
                  ))}
                  {ordersRevenue.revenue > 0 && (
                    <tr>
                      <td style={{ paddingLeft:28 }}>手動開單</td>
                      <td style={{ textAlign:'right', fontFamily:'var(--mono)', color:'var(--cyan)' }}>{fmt.currency(ordersRevenue.revenue)}</td>
                    </tr>
                  )}
                  <tr className="pnl-total-row">
                    <td style={{ fontWeight:700, paddingLeft:12 }}>銷貨收入合計</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', fontWeight:700 }}>{fmt.currency(totalRevenue)}</td>
                  </tr>

                  <tr className="pnl-section-row"><td colSpan={2} style={{ paddingLeft:16 }}>二、銷貨成本</td></tr>
                  <tr>
                    <td style={{ paddingLeft:28 }}>銷貨成本合計</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', color:'var(--pink)' }}>{fmt.currency(totalCost)}</td>
                  </tr>
                  <tr className="pnl-total-row">
                    <td style={{ fontWeight:700, paddingLeft:12 }}>毛利</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', fontWeight:700, color:'var(--green)' }}>{fmt.currency(totalGross)}</td>
                  </tr>
                  <tr>
                    <td style={{ paddingLeft:12, color:'rgba(180,180,255,0.85)', fontWeight:500 }}>毛利率</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', color:'var(--green)' }}>{fmt.pct(totalGross/totalRevenue)}</td>
                  </tr>

                  <tr className="pnl-section-row"><td colSpan={2} style={{ paddingLeft:16 }}>三、行銷費用（各賣場廣告費）</td></tr>
                  {storeRows.filter(s => s.ad > 0).map(s => (
                    <tr key={s.id}>
                      <td style={{ paddingLeft:28 }}>{s.name} 廣告費</td>
                      <td style={{ textAlign:'right', fontFamily:'var(--mono)', color:'var(--yellow)' }}>{fmt.currency(s.ad)}</td>
                    </tr>
                  ))}
                  {totalAd === 0 && (
                    <tr>
                      <td style={{ paddingLeft:28, color:'var(--muted)' }}>尚未輸入廣告費（在「各賣場廣告費」Tab 輸入）</td>
                      <td style={{ textAlign:'right', fontFamily:'var(--mono)', color:'var(--muted)' }}>$0</td>
                    </tr>
                  )}
                  <tr className="pnl-total-row">
                    <td style={{ fontWeight:700, paddingLeft:12 }}>廣告費合計</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', fontWeight:700, color:'var(--yellow)' }}>{fmt.currency(totalAd)}</td>
                  </tr>

                  <tr className="pnl-section-row"><td colSpan={2} style={{ paddingLeft:16 }}>四、其他營業費用</td></tr>
                  <tr>
                    <td colSpan={2} style={{ paddingLeft:28, paddingBottom:6, fontSize:12, color:'var(--muted)' }}>
                      ◈ 以下請輸入含稅金額，跟銷售收入/成本的計算基準一致{viewMode==='all' ? '（目前顯示每月加總，不可編輯，請切換到特定月份才能輸入）' : ''}
                    </td>
                  </tr>
                  {EXPENSE_ITEMS.map(item => (
                    <tr key={item}>
                      <td style={{ paddingLeft:28 }}>{item}</td>
                      <td style={{ padding:0 }}>
                        <div className="money-input" style={viewMode==='all' ? { opacity:0.55 } : undefined}>
                          <span className="money-input-prefix">$</span>
                          <input type="text" inputMode="numeric"
                            disabled={viewMode==='all'}
                            value={effectiveExpenses[item] ? Number(effectiveExpenses[item]).toLocaleString() : ''}
                            placeholder={viewMode==='all' ? '—' : '點擊輸入'}
                            onChange={e => { const v = Number(e.target.value.replace(/,/g,'')); setExpenses(p => ({ ...p, [item]:isNaN(v)?0:v })); setSaved(false); }}
                          />
                        </div>
                      </td>
                    </tr>
                  ))}

                  {/* 自訂費用項目：固定的11項以外，使用者自己輸入名稱＋備註的費用列 */}
                  {effectiveCustom.map(row => (
                    <tr key={row.id}>
                      <td style={{ paddingLeft:28 }}>
                        {viewMode === 'month' ? (
                          <input className="form-input" style={{ fontSize:14 }}
                            placeholder="自訂費用名稱（例：臨時倉租、活動贊助...）"
                            value={row.name}
                            onChange={e => updateCustomRow(row.id, 'name', e.target.value)}/>
                        ) : (
                          <span>{row.name}</span>
                        )}
                        {viewMode === 'month' && (
                          <input className="form-input" style={{ fontSize:12, marginTop:4, color:'var(--muted)' }}
                            placeholder="備註（選填）"
                            value={row.note}
                            onChange={e => updateCustomRow(row.id, 'note', e.target.value)}/>
                        )}
                        {viewMode === 'all' && row.note && (
                          <div style={{ fontSize:12, color:'var(--muted)' }}>{row.note}</div>
                        )}
                      </td>
                      <td style={{ padding:0, verticalAlign:'top' }}>
                        <div style={{ display:'flex', alignItems:'center' }}>
                          <div className="money-input" style={viewMode==='all' ? { opacity:0.55, flex:1 } : { flex:1 }}>
                            <span className="money-input-prefix">$</span>
                            <input type="text" inputMode="numeric"
                              disabled={viewMode==='all'}
                              value={row.amount ? Number(row.amount).toLocaleString() : ''}
                              placeholder={viewMode==='all' ? '—' : '點擊輸入'}
                              onChange={e => { const v = Number(e.target.value.replace(/,/g,'')); updateCustomRow(row.id, 'amount', isNaN(v)?0:v); setSaved(false); }}
                            />
                          </div>
                          {viewMode === 'month' && (
                            <span style={{ color:'var(--muted)', cursor:'pointer', fontSize:16, padding:'0 8px' }}
                              onClick={() => removeCustomRow(row.id)}>✕</span>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                  {viewMode === 'month' && (
                    <tr>
                      <td colSpan={2} style={{ paddingLeft:28, paddingTop:6, paddingBottom:10 }}>
                        <button className="btn btn-ghost btn-sm" onClick={addCustomRow}>＋ 新增自訂費用項目</button>
                      </td>
                    </tr>
                  )}

                  <tr className="pnl-total-row">
                    <td style={{ fontWeight:700, paddingLeft:12 }}>其他費用合計</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', fontWeight:700, color:'var(--yellow)' }}>{fmt.currency(totalExpenses)}</td>
                  </tr>

                  <tr style={{ background: totalNet>=0?'rgba(0,255,159,0.08)':'rgba(255,0,110,0.08)' }}>
                    <td style={{ fontWeight:700, fontSize:17, paddingLeft:12, color: totalNet>=0?'var(--green)':'var(--pink)', fontFamily:'var(--title)', letterSpacing:2 }}>本期淨利</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', fontSize:20, fontWeight:700, color: totalNet>=0?'var(--green)':'var(--pink)', padding:14, textShadow:`0 0 12px ${totalNet>=0?'var(--green)':'var(--pink)'}60` }}>
                      {fmt.currency(totalNet)}
                    </td>
                  </tr>
                  <tr>
                    <td style={{ paddingLeft:12, color:'rgba(180,180,255,0.85)', fontWeight:500 }}>淨利率</td>
                    <td style={{ textAlign:'right', fontFamily:'var(--mono)', color: totalNet>=0?'var(--green)':'var(--pink)' }}>{fmt.pct(totalNet/totalRevenue)}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          <div style={{ display:'flex', flexDirection:'column', gap:12 }}>
            {[
              { label:'銷貨收入', value:totalRevenue, color:'var(--cyan)',   bg:'rgba(0,245,255,0.06)',   border:'rgba(0,245,255,0.2)' },
              { label:'銷貨成本', value:totalCost,    color:'var(--pink)',   bg:'rgba(255,0,110,0.06)',   border:'rgba(255,0,110,0.2)' },
              { label:'毛利',     value:totalGross,   color:'var(--green)',  bg:'rgba(0,255,159,0.06)',   border:'rgba(0,255,159,0.2)', sub:`毛利率 ${fmt.pct(totalGross/totalRevenue)}` },
              { label:'廣告費合計', value:totalAd,    color:'var(--yellow)', bg:'rgba(245,196,0,0.06)',   border:'rgba(245,196,0,0.2)' },
              { label:'其他費用', value:totalExpenses,color:'var(--yellow)', bg:'rgba(245,196,0,0.04)',   border:'rgba(245,196,0,0.12)' },
              { label:'本期淨利', value:totalNet, color: totalNet>=0?'var(--green)':'var(--pink)', bg: totalNet>=0?'rgba(0,255,159,0.08)':'rgba(255,0,110,0.08)', border: totalNet>=0?'rgba(0,255,159,0.3)':'rgba(255,0,110,0.3)', big:true, sub:`淨利率 ${fmt.pct(totalNet/totalRevenue)}` },
            ].map(({ label, value, color, bg, border, sub, big }) => (
              <div key={label} style={{ background:bg, border:`1px solid ${border}`, borderRadius:4, padding:'13px 17px', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                <div>
                  <div style={{ fontSize:13, color, fontWeight:500, letterSpacing:1, textTransform:'uppercase', marginBottom:2 }}>{label}</div>
                  {sub && <div style={{ fontSize:12, color, opacity:0.7 }}>{sub}</div>}
                </div>
                <div style={{ fontSize:big?24:18, fontWeight:700, color, fontFamily:big?'var(--title)':'var(--mono)', textShadow:`0 0 ${big?12:6}px ${color}50` }}>
                  {fmt.currency(value)}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}